import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AccessibilityInfo, PanResponder, Platform, Pressable, StyleSheet, Text, View } from 'react-native';
import { Canvas, Circle, Group, RadialGradient, vec } from '@shopify/react-native-skia';
import Animated, { useAnimatedStyle, useDerivedValue, useFrameCallback, useSharedValue, type SharedValue } from 'react-native-reanimated';
import { bubbleRadius, clamp, hexToRgb, insetBounds, pickBody, popKick, shade, spawnBodies, stepBodies, wobbleScale, DEFAULT_PHYSICS, type BubbleBody, type BubblePointer } from './physicsMath';

export type BubbleItem = { id: string; label: string; color?: string };
export type BubbleFeedback = 'grab' | 'fling' | 'select' | 'deselect';
export type BubblePickerProps = {
  items: BubbleItem[];
  /** Controlled selection. Omit (with defaultSelectedIds) for uncontrolled. */
  selectedIds?: readonly string[];
  defaultSelectedIds?: readonly string[];
  onSelectionChange?: (ids: string[]) => void;
  onFeedback?: (event: BubbleFeedback, id: string) => void;
  multiSelect?: boolean;
  width?: number;
  height?: number;
  label?: string;
  reducedMotion?: boolean;
  /** Steps the simulation about four times slower so you can watch the collisions. Ignored while Reduce Motion is on. */
  slowMotion?: boolean;
};

const PALETTE = ['#e2725b', '#f2a65a', '#7fb069', '#5ca4a9', '#8e7cc3', '#d6679a', '#f0c05a', '#5b8e7d', '#588b8b', '#c8553d'];
const PAD = 10;

export function itemColor(item: BubbleItem, index: number) {
  return item.color ?? PALETTE[index % PALETTE.length];
}

// One bubble's Skia half: glossy gradient ball, highlight, selection ring.
function BubbleBall({ bodies, index, color }: { bodies: SharedValue<BubbleBody[]>; index: number; color: string }) {
  const baseR = useMemo(() => ({ r: bodies.value[index].baseR }), []); // eslint-disable-line react-hooks/exhaustive-deps
  const r = useDerivedValue(() => bodies.value[index].r * bodies.value[index].scale);
  const transform = useDerivedValue(() => {
    const b = bodies.value[index];
    const w = wobbleScale(b.wob);
    return [{ translateX: b.x }, { translateY: b.y }, { scaleX: w.scaleX }, { scaleY: w.scaleY }];
  });
  const ringOpacity = useDerivedValue(() => bodies.value[index].selected);
  const hi = useMemo(() => shade(color, 0.55), [color]);
  const edge = useMemo(() => shade(color, -0.14), [color]);
  const R = baseR.r;
  return (
    <Group transform={transform}>
      <Circle cx={0} cy={0} r={r}>
        <RadialGradient c={vec(-R * 0.3, -R * 0.35)} r={R * 1.75} colors={[hi, color, edge]} />
      </Circle>
      <Circle cx={-R * 0.3} cy={-R * 0.36} r={R * 0.24} color="#ffffff" opacity={0.5} />
      <Circle cx={0} cy={0} r={r} style="stroke" strokeWidth={3.5} color="#ffffff" opacity={ringOpacity} />
    </Group>
  );
}

// One bubble's DOM half: upright label and the accessible press target.
function BubbleLabel({ bodies, index, item, color, selected, onToggle }: { bodies: SharedValue<BubbleBody[]>; index: number; item: BubbleItem; color: string; selected: boolean; onToggle: (id: string) => void }) {
  const width = useMemo(() => bodies.value[index].baseR * 2 + 28, []); // eslint-disable-line react-hooks/exhaustive-deps
  const style = useAnimatedStyle(() => {
    const b = bodies.value[index];
    return { left: b.x - width / 2, top: b.y - 16, opacity: 1 };
  });
  const ink = useMemo(() => { const [r, g, b] = hexToRgb(color); return r * 0.3 + g * 0.59 + b * 0.11 > 150 ? '#23312b' : '#ffffff'; }, [color]);
  return (
    <Animated.View pointerEvents="box-none" style={[{ position: 'absolute', width, height: 32, alignItems: 'center', justifyContent: 'center' }, style]}>
      <Pressable accessibilityRole="button" accessibilityLabel={item.label} accessibilityState={{ selected }} onPress={() => onToggle(item.id)} hitSlop={8} style={({ pressed }) => [{ minHeight: 32, justifyContent: 'center', opacity: pressed ? 0.7 : 1 }]}>
        <Text style={{ color: ink, fontSize: 13, fontWeight: '700', textAlign: 'center' }}>{item.label}</Text>
      </Pressable>
    </Animated.View>
  );
}

export function BubblePicker({ items, selectedIds, defaultSelectedIds, onSelectionChange, onFeedback, multiSelect = true, width = 340, height = 380, label = 'Choose topics', reducedMotion, slowMotion = false }: BubblePickerProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const [internal, setInternal] = useState<readonly string[]>(defaultSelectedIds ?? []);
  const selection = selectedIds ?? internal;
  const bounds = useMemo(() => insetBounds(width, height, PAD), [width, height]);
  const bodies = useSharedValue<BubbleBody[]>([]);
  const pointer = useSharedValue<BubblePointer>({ x: 0, y: 0, active: 0 });
  const grabbedIndex = useRef(-1);
  const latest = useRef({ items, selection, onSelectionChange, onFeedback, multiSelect, reduce });
  latest.current = { items, selection, onSelectionChange, onFeedback, multiSelect, reduce };

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled().then(v => { if (alive) setSystemReduce(v); }).catch(() => {});
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setSystemReduce);
    return () => { alive = false; sub.remove(); };
  }, []);

  // Spawn once per item set; re-sync selection flags from props/state.
  useEffect(() => {
    const spawned = spawnBodies(items, bounds);
    bodies.value = spawned.map(b => {
      const sel = latest.current.selection.includes(b.id) ? 1 : 0;
      return { ...b, selected: sel, r: b.baseR * (sel ? 1.24 : 1) };
    });
    grabbedIndex.current = -1;
    pointer.value = { x: 0, y: 0, active: 0 };
  }, [items, bounds, bodies, pointer]);

  useEffect(() => {
    bodies.value = bodies.value.map(b => {
      const sel = latest.current.selection.includes(b.id) ? 1 : 0;
      return sel === b.selected ? b : { ...b, selected: sel, scaleV: b.scaleV + popKick(sel) };
    });
  }, [selection, bodies]);

  useFrameCallback((frame) => {
    const dt = frame.timeSincePreviousFrame ?? 16;
    const scaled = latest.current.reduce ? Math.min(dt, 48) : dt * (slowMotion ? 0.25 : 1);
    const opts = latest.current.reduce
      ? { ...DEFAULT_PHYSICS, gravity: 0, drag: 2.6 }
      : DEFAULT_PHYSICS;
    bodies.value = stepBodies(bodies.value, scaled, bounds, pointer.value, opts);
    if (latest.current.reduce) {
      // Reduce Motion: settle the decorative oscillators immediately.
      bodies.value = bodies.value.map(b => ({ ...b, wob: 0, wobV: 0, scale: 1, scaleV: 0 }));
    }
  });

  const toggle = useCallback((id: string) => {
    const cur = latest.current.selection;
    const on = cur.includes(id);
    let next: readonly string[];
    if (on) next = cur.filter(x => x !== id);
    else next = latest.current.multiSelect ? [...cur, id] : [id];
    if (!selectedIds) setInternal(next);
    latest.current.onSelectionChange?.([...next]);
    latest.current.onFeedback?.(on ? 'deselect' : 'select', id);
  }, [selectedIds]);

  const pan = useMemo(() => PanResponder.create({
    onStartShouldSetPanResponder: () => false,
    onMoveShouldSetPanResponderCapture: (_e, g) => Math.abs(g.dx) + Math.abs(g.dy) > 6,
    onPanResponderGrant: (e) => {
      const x = e.nativeEvent.locationX, y = e.nativeEvent.locationY;
      const idx = pickBody(bodies.value, x, y);
      grabbedIndex.current = idx;
      pointer.value = { x, y, active: 1 };
      if (idx >= 0) {
        bodies.value = bodies.value.map((b, i) => (i === idx ? { ...b, grabbed: 1 } : b));
        latest.current.onFeedback?.('grab', bodies.value[idx].id);
      }
    },
    onPanResponderMove: (e) => { pointer.value = { x: e.nativeEvent.locationX, y: e.nativeEvent.locationY, active: 1 }; },
    onPanResponderRelease: (e, g) => {
      const idx = grabbedIndex.current;
      pointer.value = { x: e.nativeEvent.locationX, y: e.nativeEvent.locationY, active: 0 };
      if (idx >= 0) {
        const kick = clamp(Math.hypot(g.vx, g.vy) * 1000, 0, DEFAULT_PHYSICS.maxSpeed);
        bodies.value = bodies.value.map((b, i) => (i === idx ? { ...b, grabbed: 0, vx: g.vx * 900, vy: g.vy * 900 } : b));
        latest.current.onFeedback?.(kick > 500 ? 'fling' : 'grab', bodies.value[idx].id);
        grabbedIndex.current = -1;
      }
    },
    onPanResponderTerminate: (e) => {
      const idx = grabbedIndex.current;
      pointer.value = { x: e.nativeEvent.locationX, y: e.nativeEvent.locationY, active: 0 };
      if (idx >= 0) { bodies.value = bodies.value.map((b, i) => (i === idx ? { ...b, grabbed: 0 } : b)); grabbedIndex.current = -1; }
    },
  }), [bodies, pointer]);

  return (
    <View style={{ width, height, borderRadius: 24, backgroundColor: '#10201a', overflow: 'hidden' }} accessibilityLabel={label}>
      <Canvas pointerEvents="none" style={{ width, height }}>
        {items.map((item, i) => <BubbleBall key={item.id} bodies={bodies} index={i} color={itemColor(item, i)} />)}
      </Canvas>
      <View style={StyleSheet.absoluteFill} {...pan.panHandlers}>
        {items.map((item, i) => <BubbleLabel key={item.id} bodies={bodies} index={i} item={item} color={itemColor(item, i)} selected={selection.includes(item.id)} onToggle={toggle} />)}
      </View>
    </View>
  );
}

// Pure 2D physics for the Bubble Picker. Every function is a worklet so
// Reanimated can step the simulation on the UI thread; plain JS (tests, web
// preview) ignores the tag. No randomness: spawns and sizes are deterministic
// so tests, native and web all agree.

export type BubbleBody = {
  id: string;
  x: number; y: number;       // center, px
  vx: number; vy: number;     // velocity, px/s
  r: number;                  // current radius, px (springs toward target)
  baseR: number;              // resting radius, px
  rv: number;                 // radius spring velocity
  selected: number;           // 0 or 1
  scale: number; scaleV: number; // pop spring (1 = rest)
  wob: number; wobV: number;  // impact wobble oscillator (0 = still)
  grabbed: number;            // 0 or 1
};
export type BubbleBounds = { left: number; top: number; right: number; bottom: number };
export type BubblePointer = { x: number; y: number; active: number };
export type PhysicsOptions = {
  gravity: number;      // constant pull toward the bounds center, px/s^2
  drag: number;         // exponential velocity damping, 1/s
  restitution: number;  // bounce energy kept, 0..1
  maxSpeed: number;     // px/s, stability cap
};

export const DEFAULT_PHYSICS: PhysicsOptions = { gravity: 34, drag: 1.05, restitution: 0.86, maxSpeed: 2600 };

// Springs: radius breathes toward its target, scale pops on selection, wobble
// rings after an impact. Tuned so a tap feels like a soft rubber ball.
const RADIUS_SPRING = { k: 210, c: 17 };
const SCALE_SPRING = { k: 300, c: 13 };
const WOBBLE_SPRING = { k: 130, c: 4.2 };
const GRAB_SPRING = { k: 150, c: 15 };
const SELECTED_GROWTH = 1.24;
const IMPACT_WOBBLE = 0.0035;   // wobble kick per px/s of impact speed
const MAX_WOBBLE = 0.09;

export function clamp(value: number, min: number, max: number) {
  'worklet';
  return Math.max(min, Math.min(max, Number.isFinite(value) ? value : min));
}

// Small deterministic hash so bubble sizes and spawn jitter are stable across
// platforms and test runs.
export function hashSeed(id: string, salt: number) {
  'worklet';
  let h = (2166136261 + salt * 101) >>> 0;
  for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 16777619) >>> 0;
  return (h % 100000) / 100000;
}

export function bubbleRadius(id: string, index: number) {
  'worklet';
  return 34 + Math.floor(hashSeed(id, index * 7 + 1) * 3) * 5; // 34, 39 or 44
}

export function insetBounds(width: number, height: number, pad: number): BubbleBounds {
  'worklet';
  const p = Math.max(0, pad);
  return { left: p, top: p, right: Math.max(p, width - p), bottom: Math.max(p, height - p) };
}

// Golden-angle spiral from the center: bubbles start clustered, never stacked.
export function spawnBodies(items: readonly { id: string }[], bounds: BubbleBounds): BubbleBody[] {
  'worklet';
  const cx = (bounds.left + bounds.right) / 2, cy = (bounds.top + bounds.bottom) / 2;
  const golden = Math.PI * (3 - Math.sqrt(5));
  return items.map((item, i) => {
    const r = bubbleRadius(item.id, i);
    const angle = i * golden;
    const ring = 8 + Math.sqrt(i + 0.5) * (r + 14);
    return {
      id: item.id,
      x: clamp(cx + Math.cos(angle) * ring, bounds.left + r, bounds.right - r),
      y: clamp(cy + Math.sin(angle) * ring * 0.82, bounds.top + r, bounds.bottom - r),
      vx: 0, vy: 0, r, baseR: r, rv: 0, selected: 0, scale: 1, scaleV: 0, wob: 0, wobV: 0, grabbed: 0,
    };
  });
}

// Topmost body under a point: the last spawned wins, like painter order.
export function pickBody(bodies: readonly BubbleBody[], x: number, y: number) {
  'worklet';
  for (let i = bodies.length - 1; i >= 0; i--) {
    const b = bodies[i], dx = x - b.x, dy = y - b.y, rr = b.r * b.scale + 6;
    if (dx * dx + dy * dy <= rr * rr) return i;
  }
  return -1;
}

export function totalSpeed(bodies: readonly BubbleBody[]) {
  'worklet';
  let s = 0;
  for (let i = 0; i < bodies.length; i++) s += Math.abs(bodies[i].vx) + Math.abs(bodies[i].vy);
  return s;
}

function substep(bodies: BubbleBody[], h: number, bounds: BubbleBounds, pointer: BubblePointer, opts: PhysicsOptions) {
  'worklet';
  const cx = (bounds.left + bounds.right) / 2, cy = (bounds.top + bounds.bottom) / 2;
  for (let i = 0; i < bodies.length; i++) {
    const b = bodies[i];
    let ax = 0, ay = 0;
    if (b.grabbed) {
      // Grab joint: a stiff damped spring to the finger. Fling velocity comes
      // for free because the spring is still catching up when you let go.
      ax = GRAB_SPRING.k * (pointer.x - b.x) - GRAB_SPRING.c * b.vx;
      ay = GRAB_SPRING.k * (pointer.y - b.y) - GRAB_SPRING.c * b.vy;
    } else if (opts.gravity > 0) {
      const dx = cx - b.x, dy = cy - b.y, d = Math.sqrt(dx * dx + dy * dy);
      if (d > 2) { ax = (opts.gravity * dx) / d; ay = (opts.gravity * dy) / d; }
    }
    b.vx += ax * h; b.vy += ay * h;
    const f = Math.exp(-opts.drag * h);
    b.vx *= f; b.vy *= f;
    const speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
    if (speed > opts.maxSpeed) { b.vx = (b.vx / speed) * opts.maxSpeed; b.vy = (b.vy / speed) * opts.maxSpeed; }
    b.x += b.vx * h; b.y += b.vy * h;
    // Radius breathes toward selected/resting size.
    const targetR = b.baseR * (b.selected ? SELECTED_GROWTH : 1);
    b.rv += (RADIUS_SPRING.k * (targetR - b.r) - RADIUS_SPRING.c * b.rv) * h;
    b.r = Math.max(4, b.r + b.rv * h);
    // Pop spring relaxes to 1; selection toggles kick scaleV from outside.
    b.scaleV += (SCALE_SPRING.k * (1 - b.scale) - SCALE_SPRING.c * b.scaleV) * h;
    b.scale += b.scaleV * h;
    // Impact wobble rings down.
    b.wobV += (-WOBBLE_SPRING.k * b.wob - WOBBLE_SPRING.c * b.wobV) * h;
    b.wob += b.wobV * h;
    if (Math.abs(b.wob) < 0.0004 && Math.abs(b.wobV) < 0.004) { b.wob = 0; b.wobV = 0; }
  }
  // Circle-circle collisions: positional correction plus an impulse with
  // restitution. Grabbed bubbles push harder, as if heavier.
  for (let i = 0; i < bodies.length; i++) {
    for (let j = i + 1; j < bodies.length; j++) {
      const a = bodies[i], b = bodies[j];
      const dx = b.x - a.x, dy = b.y - a.y;
      const min = a.r + b.r;
      const d2 = dx * dx + dy * dy;
      if (d2 >= min * min || d2 < 1e-6) continue;
      const d = Math.sqrt(d2), nx = dx / d, ny = dy / d;
      const ma = a.r * a.r, mb = b.r * b.r;
      const ima = (1 / ma) * (a.grabbed ? 0.15 : 1), imb = (1 / mb) * (b.grabbed ? 0.15 : 1);
      const corr = ((min - d) / (ima + imb)) * 0.8;
      a.x -= nx * corr * ima; a.y -= ny * corr * ima;
      b.x += nx * corr * imb; b.y += ny * corr * imb;
      const vn = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
      if (vn < 0) {
        const jimp = (-(1 + opts.restitution) * vn) / (ima + imb);
        a.vx -= nx * jimp * ima; a.vy -= ny * jimp * ima;
        b.vx += nx * jimp * imb; b.vy += ny * jimp * imb;
        const kick = clamp(Math.abs(vn) * IMPACT_WOBBLE, 0, MAX_WOBBLE * 2);
        a.wobV += kick; b.wobV += kick;
      }
    }
  }
  // Walls: clamp inside, bounce, wobble on a hard hit.
  for (let i = 0; i < bodies.length; i++) {
    const b = bodies[i], e = opts.restitution;
    if (b.x < bounds.left + b.r) { b.x = bounds.left + b.r; if (b.vx < 0) { b.wobV += clamp(-b.vx * IMPACT_WOBBLE, 0, MAX_WOBBLE * 2); b.vx = -b.vx * e; } }
    if (b.x > bounds.right - b.r) { b.x = bounds.right - b.r; if (b.vx > 0) { b.wobV += clamp(b.vx * IMPACT_WOBBLE, 0, MAX_WOBBLE * 2); b.vx = -b.vx * e; } }
    if (b.y < bounds.top + b.r) { b.y = bounds.top + b.r; if (b.vy < 0) { b.wobV += clamp(-b.vy * IMPACT_WOBBLE, 0, MAX_WOBBLE * 2); b.vy = -b.vy * e; } }
    if (b.y > bounds.bottom - b.r) { b.y = bounds.bottom - b.r; if (b.vy > 0) { b.wobV += clamp(b.vy * IMPACT_WOBBLE, 0, MAX_WOBBLE * 2); b.vy = -b.vy * e; } }
  }
}

// Advance the field by dtMs milliseconds with fixed 120 Hz substeps so fast
// flings stay stable. Returns a fresh array (shared-value friendly).
export function stepBodies(prev: readonly BubbleBody[], dtMs: number, bounds: BubbleBounds, pointer: BubblePointer, opts: PhysicsOptions): BubbleBody[] {
  'worklet';
  const bodies = prev.map(b => ({ ...b }));
  const dt = clamp(dtMs, 0, 48) / 1000;
  if (dt <= 0) return bodies;
  const steps = Math.max(1, Math.ceil(dt * 120));
  const h = dt / steps;
  for (let s = 0; s < steps; s++) substep(bodies, h, bounds, pointer, opts);
  return bodies;
}

// Selection pop: kick the scale spring so the bubble overshoots once.
export function popKick(selected: number) {
  'worklet';
  return selected ? 2.6 : -1.8;
}

// Wobble renders as a skewed squash: scaleX/scaleY oscillate out of phase.
export function wobbleScale(wob: number) {
  'worklet';
  const w = clamp(wob, -MAX_WOBBLE, MAX_WOBBLE);
  return { scaleX: 1 + w, scaleY: 1 - w };
}

export function hexToRgb(hex: string): [number, number, number] {
  'worklet';
  let h = hex.replace('#', '');
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const n = parseInt(h.length === 6 ? h : '888888', 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

// f > 0 lightens toward white, f < 0 darkens toward black.
export function shade(hex: string, f: number) {
  'worklet';
  const [r, g, b] = hexToRgb(hex);
  const t = f > 0 ? 255 : 0, p = Math.min(1, Math.abs(f));
  const c = (v: number) => Math.round(clamp(v + (t - v) * p, 0, 255));
  return `rgb(${c(r)}, ${c(g)}, ${c(b)})`;
}

import React, { useCallback, useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import { BubblePicker, type BubbleItem, type BubblePickerProps } from './BubblePicker';

const topics: BubbleItem[] = [
  { id: 'music', label: 'Music', color: '#e2725b' },
  { id: 'travel', label: 'Travel', color: '#5ca4a9' },
  { id: 'food', label: 'Food', color: '#f2a65a' },
  { id: 'tech', label: 'Tech', color: '#8e7cc3' },
  { id: 'art', label: 'Art', color: '#d6679a' },
  { id: 'sport', label: 'Sport', color: '#7fb069' },
  { id: 'books', label: 'Books', color: '#f0c05a' },
  { id: 'film', label: 'Film', color: '#588b8b' },
  { id: 'photo', label: 'Photo', color: '#c8553d' },
  { id: 'games', label: 'Games', color: '#5b8e7d' },
];

export default function Example({ onFeedback }: { onFeedback?: BubblePickerProps['onFeedback'] }) {
  const [selected, setSelected] = useState<string[]>([]);
  const [slow, setSlow] = useState(false);
  const [reduce, setReduce] = useState<boolean | undefined>();
  const onSelection = useCallback((ids: string[]) => setSelected(ids), []);
  return (
    <View style={{ paddingVertical: 24, width: '100%', alignItems: 'center' }}>
      <Text accessibilityLiveRegion="polite" style={{ color: '#31513b', fontSize: 13, marginBottom: 12 }}>
        {selected.length === 0 ? 'Tap bubbles to pick topics' : `Picked ${selected.length}: ${selected.join(', ')}`}
      </Text>
      <BubblePicker items={topics} label="Choose topics" slowMotion={slow} reducedMotion={reduce} onSelectionChange={onSelection} onFeedback={onFeedback} />
      <Text style={{ color: '#4b6053', fontSize: 12, marginTop: 16 }}>Drag to fling. Tap a bubble to select it.</Text>
      <View style={{ flexDirection: 'row', gap: 8, marginTop: 10 }}>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} accessibilityLabel="Slow motion" onPress={() => setSlow(!slow)} style={{ minHeight: 44, paddingHorizontal: 16, borderRadius: 14, backgroundColor: '#e6edde', justifyContent: 'center' }}><Text style={{ color: '#31513b', fontSize: 13 }}>Slow motion: {slow ? 'on' : 'off'}</Text></Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce === true }} accessibilityLabel="Reduced motion" onPress={() => setReduce(reduce === true ? undefined : true)} style={{ minHeight: 44, paddingHorizontal: 16, borderRadius: 14, backgroundColor: '#e6edde', justifyContent: 'center' }}><Text style={{ color: '#31513b', fontSize: 13 }}>Motion: {reduce === true ? 'reduced' : 'system'}</Text></Pressable>
      </View>
    </View>
  );
}
